mapper.update:
update project_milestone
NAME_MILESTONE = #{nameMilestone,jdbcType=VARCHAR}, DT_MILESTONE = #{dtMilestone,jdbcType=DATE}, CD_STATUS = #{cdStatus,jdbcType=VARCHAR}, CD_DESCRIPTION = #{cdDescription,jdbcType=VARCHAR},
where ID_MILESTONE = #{idMilestone,jdbcType=VARCHAR}

mapper.select:
select

from project_milestone
where CD_STATUS <> '已达成'
  and DT_MILESTONE >= #{from,jdbcType=DATE}
  and DT_MILESTONE <= #{to,jdbcType=DATE}
order by DT_MILESTONE
